  function disclaimer() { pop('Disclaimer', '', '<p class="smx-disc">' + "The Chattanooga Thrift Trail exists to make it easy to find good deals. It is a self-guided map of thrift shops, vintage shops and antique shops around the Chattanooga area. It builds an efficient driving route around each shop&rsquo;s hours, so you can visit the most shops with the least driving, and it offers hand-picked loops, the Lookout Loop and the Scenic City Loop, for a nice drive.<br><br>The information provided on this page, including shop hours, addresses, and location data, is provided for general informational purposes only and is not guaranteed to be accurate, complete, or current. Shop hours, inventory, and availability are subject to change without notice. Route optimization, estimated travel times, and distances are approximations only and should not be relied upon for time-sensitive planning. Users are advised to independently verify shop hours and availability before visiting. This site assumes no liability for any inaccuracies, changes, or inconvenience resulting from reliance on the information provided herein. This site may use Google Analytics to count visits and see which features are used; no names or contact details are collected through it. If you choose to add a name or email under Account, your name is kept only on your own device, and your email, if you add one, is sent to the site&rsquo;s moderators so they can contact you about the Trail. It is never shown publicly." + '</p>'); }
  function homescreen() { pop('Get the Trail web app', '', '<div class="ctt-homescreen-panel" style="margin:0">' + "\n    <h3>Get the Trail web app</h3>\n    <p>Add it to your home screen and it opens like an app, with one tap. Nothing to download, no account, and updates arrive on their own.</p>\n    <div class=\"ctt-homescreen-cols\">\n      <div>\n        <h4>iPhone &amp; iPad (Safari)</h4>\n        <ol>\n          <li>Open this page in <strong>Safari</strong>, not inside Facebook, Instagram, or another app&rsquo;s built-in browser.</li>\n          <li>Tap the <strong>Share</strong> button (the square with an arrow pointing up).</li>\n          <li>Scroll down and tap <strong>Add to Home Screen</strong>. If you don&rsquo;t see it, tap <strong>View More</strong> first.</li>\n          <li>Tap <strong>Add</strong>.</li>\n        </ol>\n      </div>\n      <div>\n        <h4>Android (Chrome)</h4>\n        <ol>\n          <li>Open this page in <strong>Chrome</strong>.</li>\n          <li>Tap the <strong>three dots</strong> at the top right.</li>\n          <li>Tap <strong>Add to Home screen</strong> (or <strong>Install app</strong> if you see that instead).</li>\n          <li>Tap <strong>Add</strong> or <strong>Install</strong>.</li>\n        </ol>\n        <p style=\"margin:0;\"><strong>Samsung Internet:</strong> tap the menu (three lines), then <strong>Add page to</strong>, then <strong>Home screen</strong>.</p>\n      </div>\n      <div>\n        <h4>Mac</h4>\n        <ol>\n          <li><strong>Safari</strong> (macOS Sonoma or newer): open the <strong>File</strong> menu and choose <strong>Add to Dock&hellip;</strong>, then click <strong>Add</strong>.</li>\n          <li><strong>Chrome:</strong> click the <strong>three dots</strong>, then <strong>Save and share</strong> (older versions: <strong>Cast, save, and share</strong>), then <strong>Install page as app</strong>.</li>\n        </ol>\n      </div>\n      <div>\n        <h4>Windows PC</h4>\n        <ol>\n          <li><strong>Chrome:</strong> click the <strong>three dots</strong>, then <strong>Save and share</strong> (older versions: <strong>Cast, save, and share</strong>), then <strong>Install page as app</strong>.</li>\n          <li><strong>Edge:</strong> click the <strong>three dots</strong>, then <strong>Apps</strong>, then <strong>Install this site as an app</strong>.</li>\n        </ol>\n      </div>\n    </div>\n    <p class=\"ctt-homescreen-note\">On an iPhone, the home-screen shortcut can keep its own saved progress, separate from what you did in Safari.</p>".replace(/<h3>.*?<\/h3>/, '') + '</div>'); }
